% Blockchain primitives of the contracts, for the CiaoPP cost analysis.
%
% The code is the one generated by the pipeline (identical in every contract
% that uses a primitive; the internal loops are renamed). The pipeline
% removes these predicates from the contracts, which import them through
% the package gas_model.pl. Their gas costs are trusted in gas_model.pl.
% Layout as in ciaopp_cost/examples/resources_blockchain (michelson_preds.pl
% for the primitives, the package carthage.pl for the cost model).

:- module(blockchain, [get_bal/3, set_bal/4, transfer/5, get_tok_bal/3, get_allow/4, get_owner/3, get_nft_bal/3, get_appr/3, get_op_appr/4,
                       get_paper/3, get_share/3, get_board/3], []).

% Coins. get_bal(Addr, B, Bal): Bal is the amount of the last
% bal(Addr, _) of B, or 0.
get_bal(A, B, C) :-
    get_bal_loop(B, A, 0, C).
get_bal_loop([], _, A, A).
get_bal_loop([bal(A, B)|C], D, E, F) :-
    get_bal_cond(A, D, G, B, E),
    get_bal_loop(C, D, G, F).
get_bal_cond(A, A, B, B, _) :-
    !.
get_bal_cond(_, _, A, _, A).

% set_bal(Addr, NewVal, B_in, B_out): every bal(Addr, _) of B_in gets
% NewVal. It neither adds nor removes entries, so B_out has the length of
% B_in (stated in the trust: the type domain cannot see it).
set_bal(A, B, C, D) :-
    set_bal_loop(C, A, B, D).
set_bal_loop([], _, _, []).
set_bal_loop([bal(A, B)|C], D, E, F) :-
    set_bal_cond(A, D, F, E, G, B),
    set_bal_loop(C, D, E, G).
set_bal_cond(A, A, [bal(A, B)|C], B, C, _) :-
    !.
set_bal_cond(A, _, [bal(A, B)|C], _, C, B).

% transfer(From, To, Amount, B_in, B_out): two get_bal and two set_bal.
transfer(A, B, C, D, E) :-
    get_bal(A, D, F),
    G is F,
    H is G-C,
    I is H,
    set_bal(A, I, D, J),
    get_bal(B, J, K),
    L is K,
    M is L+C,
    N is M,
    set_bal(B, N, J, E).

% Tokens. get_tok_bal(Addr, TB, Bal): amount of the first tb(Addr, _).
get_tok_bal(A, B, C) :-
    get_tok_bal_loop(B, A, 0, C).
get_tok_bal_loop([], _, A, A).
get_tok_bal_loop([tb(A, B)|C], D, E, F) :-
    get_tok_bal_cond(A, D, E, G, B),
    get_tok_bal_loop(C, D, G, F).
get_tok_bal_cond(A, A, 0, B, B) :-
    !.
get_tok_bal_cond(_, _, A, A, _).

% get_allow(Owner, Spender, AL, Amount): amount of the first
% al(Owner, Spender, _).
get_allow(A, B, C, D) :-
    get_allow_loop(C, A, B, 0, D).
get_allow_loop([], _, _, A, A).
get_allow_loop([al(A, B, C)|D], E, F, G, H) :-
    get_allow_cond(A, E, B, F, G, I, C),
    get_allow_loop(D, E, F, I, H).
get_allow_cond(A, A, B, B, 0, C, C) :-
    !.
get_allow_cond(_, _, _, _, A, A, _).

% NFTs. get_owner(TokenId, TO, Owner): owner of the first t_o(TokenId, _),
% or null.
get_owner(A, B, C) :-
    get_owner_loop(B, A, null, C).
get_owner_loop([], _, A, A).
get_owner_loop([t_o(A, B)|C], D, E, F) :-
    get_owner_cond(A, D, E, G, B),
    get_owner_loop(C, D, G, F).
get_owner_cond(A, A, null, B, B) :-
    !.
get_owner_cond(_, _, A, A, _).

% get_nft_bal(Owner, NB, Count): count of the first n_b(Owner, _), or 0.
get_nft_bal(A, B, C) :-
    get_nft_bal_loop(B, A, 0, C).
get_nft_bal_loop([], _, A, A).
get_nft_bal_loop([n_b(A, B)|C], D, E, F) :-
    get_nft_bal_cond(A, D, E, G, B),
    get_nft_bal_loop(C, D, G, F).
get_nft_bal_cond(A, A, 0, B, B) :-
    !.
get_nft_bal_cond(_, _, A, A, _).

% get_appr(TokenId, AP, Approved): approved address of the first
% app(TokenId, _), or null.
get_appr(A, B, C) :-
    get_appr_loop(B, A, null, C).
get_appr_loop([], _, A, A).
get_appr_loop([app(A, B)|C], D, E, F) :-
    get_appr_cond(A, D, E, G, B),
    get_appr_loop(C, D, G, F).
get_appr_cond(A, A, null, B, B) :-
    !.
get_appr_cond(_, _, A, A, _).

% get_op_appr(Owner, Operator, OP, Flag): flag of the first
% op(Owner, Operator, _), or 0.
get_op_appr(A, B, C, D) :-
    get_op_appr_loop(C, B, A, 0, D).
get_op_appr_loop([], _, _, A, A).
get_op_appr_loop([op(A, B, C)|D], E, F, G, H) :-
    get_op_appr_cond(A, F, B, E, G, I, C),
    get_op_appr_loop(D, E, F, I, H).
get_op_appr_cond(A, A, B, B, 0, C, C) :-
    !.
get_op_appr_cond(_, _, _, _, A, A, _).
% Contract state tables (one unit of gas per entry scanned, like the
% primitives above).

% get_paper(Voter, Papers, Paper): the first paper(Voter, _, _, _, _), or 0
% (ballot).
get_paper(A, B, C) :-
    get_paper_loop(B, A, 0, C).
get_paper_loop([], _, A, A).
get_paper_loop([paper(A, B, C, D, E)|F], G, H, I) :-
    get_paper_cond(A, G, J, B, C, D, E, H),
    get_paper_loop(F, G, J, I).
get_paper_cond(A, A, paper(A, B, C, D, E), B, C, D, E, _) :-
    !.
get_paper_cond(_, _, A, _, _, _, _, A).

% get_share(Addr, Shares, N): shares of the first sh(Addr, _), or 0
% (shared_entity, simple_shared_entity).
get_share(A, B, C) :-
    get_share_loop(B, A, 0, C).
get_share_loop([], _, A, A).
get_share_loop([sh(A, B)|C], D, E, F) :-
    get_share_cond(D, A, E, G, B),
    get_share_loop(C, D, G, F).
get_share_cond(A, A, 0, B, B) :-
    !.
get_share_cond(_, _, A, A, _).

% get_board(Pos, Board, Cell): content of the first cell(Pos, _), or 0
% (tictactoe).
get_board(A, B, C) :-
    get_board_loop(B, A, 0, C).
get_board_loop([], _, A, A).
get_board_loop([cell(A, B)|C], D, E, F) :-
    get_board_cond(A, D, E, G, B),
    get_board_loop(C, D, G, F).
get_board_cond(A, A, 0, B, B) :-
    !.
get_board_cond(_, _, A, A, _).
